import { ToggleGroup } from '@absoluteui/components/toggle-group';

const host = document.createElement('div');
document.body.append(host);
ToggleGroup.create(host, {
  label: 'Text alignment',
  required: true,
  attached: true,
  value: ['start'],
  items: [
    { value: 'start', label: 'Align start', icon: 'align-start', iconOnly: true },
    { value: 'center', label: 'Align center', icon: 'align-center', iconOnly: true },
    { value: 'end', label: 'Align end', icon: 'align-end', iconOnly: true },
  ],
});

import { ToggleGroup, type ToggleGroupChangeDetail } from '@absoluteui/components/toggle-group';

const host = document.createElement('div');
const preview = document.createElement('p');
preview.textContent = 'The quick brown fox';
document.body.append(host, preview);
ToggleGroup.create(host, {
  label: 'Text style',
  multiple: true,
  items: [
    { value: 'bold', label: 'Bold', icon: 'bold' },
    { value: 'italic', label: 'Italic', icon: 'italic' },
    { value: 'underline', label: 'Underline', icon: 'underline' },
  ],
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<ToggleGroupChangeDetail>).detail;
  preview.style.fontWeight = value.includes('bold') ? 'bold' : '';
  preview.style.fontStyle = value.includes('italic') ? 'italic' : '';
  preview.style.textDecoration = value.includes('underline') ? 'underline' : '';
});
